public class GreetingPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            GreetingPanel panel = new GreetingPanel();
            java.awt.Component label = find(panel, "greeting");
            java.awt.Component field = find(panel, "nameField");
            java.awt.Component button = find(panel, "greetButton");
            check("greeting label exists", true, label instanceof javax.swing.JLabel);
            check("button text", (button instanceof javax.swing.JButton)
                    ? ((javax.swing.JButton) button).getText() : "(missing)", "Greet");
            check("initial greeting", "Hello, stranger!", textOf(label));
            if (field instanceof javax.swing.JTextField && button instanceof javax.swing.JButton) {
                javax.swing.JTextField tf = (javax.swing.JTextField) field;
                javax.swing.JButton b = (javax.swing.JButton) button;
                tf.setText("Ada");
                b.doClick();
                check("after greeting Ada", "Hello, Ada!", textOf(label));
                tf.setText("Grace Hopper");
                b.doClick();
                check("after greeting Grace Hopper", "Hello, Grace Hopper!", textOf(label));
                tf.setText("");
                b.doClick();
                check("empty field still follows the pattern", "Hello, !", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  nameField or greetButton not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

