import java.awt.event.ActionEvent;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class GreetingPanel extends JPanel {

    private final JLabel greeting = new JLabel("Hello, stranger!");
    private final JTextField nameField = new JTextField(10);
    private final JButton greetButton = new JButton("Greet");

    public GreetingPanel() {
        greeting.setName("greeting");
        nameField.setName("nameField");
        greetButton.setName("greetButton");
        add(greeting);
        add(nameField);
        add(greetButton);
        greetButton.addActionListener(this::onGreet);
    }

    private void onGreet(ActionEvent e) {
        greeting.setText("Hello, " + nameField.getText() + "!");
    }
}
